import WellSpentAPI

/// Pure derivation of the two lists `PeriodReviewGateView` shows — split out
/// so they're unit-testable without a network call. See
/// docs/features/month-cycling-review.md.
nonisolated enum PeriodReviewFiltering {
    /// Rows in the newly-cycled period that were generated by carrying the
    /// previous period's ending balance forward.
    static func carriedOverTransactions(_ transactions: [Wellspent_V1_Transaction], previousPeriodID: String) -> [Wellspent_V1_Transaction] {
        transactions.filter { $0.carriedFromBudgetPeriodID == previousPeriodID }
    }

    /// Fixed-type rows in the period that just closed that were never marked paid.
    static func unpaidFixedTransactions(_ transactions: [Wellspent_V1_Transaction], fixedTypeID: Int32) -> [Wellspent_V1_Transaction] {
        transactions.filter { $0.transactionTypeID == fixedTypeID && !$0.isPaid }
    }
}
